'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStrides from '@stdlib/ndarray-base-strides';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import { ndarray as strided } from '@stdlib/blas-base-ssymv';


// MAIN //

/**
* Performs the matrix-vector operation `y = alpha*A*x + beta*y`, where `alpha` and `beta` are scalars, `x` and `y` are one-dimensional ndarrays, and `A` is an `N` by `N` symmetric matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a one-dimensional input ndarray corresponding to `x`.
*     -   a one-dimensional input/output ndarray corresponding to `y`.
*     -   a zero-dimensional ndarray specifying whether the upper or lower triangular part of the symmetric matrix `A` should be referenced.
*     -   a zero-dimensional ndarray containing a scalar constant corresponding to `alpha`.
*     -   a zero-dimensional ndarray containing a scalar constant corresponding to `beta`.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import Float32Matrix from '@stdlib/ndarray-matrix-float32';
* import Float32Vector from '@stdlib/ndarray-vector-float32';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
* import resolveEnum from '@stdlib/blas-base-matrix-triangle-resolve-enum';
*
* var A = new Float32Matrix( [ [ 1.0, 2.0, 3.0 ], [ 2.0, 1.0, 2.0 ], [ 3.0, 2.0, 1.0 ] ] );
* var x = new Float32Vector( [ 1.0, 2.0, 3.0 ] );
* var y = new Float32Vector( [ 4.0, 5.0, 6.0 ] );
*
* var uplo = scalar2ndarray( resolveEnum( 'upper' ), {
*     'dtype': 'int32'
* });
* var alpha = scalar2ndarray( 3.0, {
*     'dtype': 'float32'
* });
* var beta = scalar2ndarray( 2.0, {
*     'dtype': 'float32'
* });
*
* var z = ssymv( [ A, x, y, uplo, alpha, beta ] );
* // returns <ndarray>[ 50.0, 40.0, 42.0 ]
*
* var bool = ( z === y );
* // returns true
*/
function ssymv( arrays ) {
	var alpha;
	var beta;
	var uplo;
	var st;
	var A;
	var x;
	var y;

	A = arrays[ 0 ];
	x = arrays[ 1 ];
	y = arrays[ 2 ];

	uplo = ndarraylike2scalar( arrays[ 3 ] );
	alpha = ndarraylike2scalar( arrays[ 4 ] );
	beta = ndarraylike2scalar( arrays[ 5 ] );

	st = getStrides( A, false );

	strided( uplo, numelDimension( A, 0 ), alpha, getData( A ), st[ 0 ], st[ 1 ], getOffset( A ), getData( x ), getStride( x, 0 ), getOffset( x ), beta, getData( y ), getStride( y, 0 ), getOffset( y ) ); // eslint-disable-line max-len

	return y;
}


// EXPORTS //

export default ssymv;
